#!/usr/bin/env bash
set -Eeuo pipefail
export DEBIAN_FRONTEND=noninteractive
: "${DB_PASSWORD:?Required}" "${DB_USER_HOST:?Required}" "${DB_BIND:?Required}"
[[ $(id -u) -eq 0 ]] || { echo 'Must run as root' >&2; exit 1; }
apt-get update
apt-get install -y mariadb-server ufw
systemctl enable --now mariadb
cat >/etc/mysql/mariadb.conf.d/99-wordpress.cnf <<CONF
[mariadb]
bind-address = ${DB_BIND}
character-set-server = utf8mb4
collation-server = utf8mb4_unicode_ci
CONF
systemctl restart mariadb
# The password is generated by OpenTofu as alphanumeric; ensure it cannot break SQL syntax.
[[ "$DB_PASSWORD" =~ ^[A-Za-z0-9]+$ ]] || { echo 'Invalid password format' >&2; exit 1; }
mariadb --protocol=socket <<SQL
CREATE DATABASE IF NOT EXISTS wordpress CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE USER IF NOT EXISTS 'wordpress_app'@'${DB_USER_HOST}' IDENTIFIED BY '${DB_PASSWORD}';
ALTER USER 'wordpress_app'@'${DB_USER_HOST}' IDENTIFIED BY '${DB_PASSWORD}';
GRANT ALL PRIVILEGES ON wordpress.* TO 'wordpress_app'@'${DB_USER_HOST}';
SQL
if [[ "$DB_BIND" != '127.0.0.1' ]]; then
  : "${WEB_PRIVATE_IP:?Required for split mode}"
  ufw default deny incoming
  ufw default allow outgoing
  ufw allow from "$WEB_PRIVATE_IP" to "$DB_BIND" port 3306 proto tcp
  ufw allow from "$WEB_PRIVATE_IP" to any port 22 proto tcp
  ufw --force enable
fi
systemctl is-active --quiet mariadb
echo 'MariaDB ready'
